public class Pedido {
    private int numero;
    private List<ItemPedido> itens = new ArrayList<>();

    public Pedido(int numero) {
        this.numero = numero;
    }

    public void adicionarItem(String produto, int qtde, double preco) {
        this.itens.add(new ItemPedido(produto, qtde, preco));
    }

    public double calcularTotal() {
        double total = 0;
        for (ItemPedido item : itens) {
            total += item.subtotal();
        }
        return total;
    }
}

public class Conta {
    private int numero;
    private double saldo;

    public Conta(int numero, double saldo) {
        if (saldo < 0) {
            throw new IllegalArgumentException("Saldo inicial negativo");
        }
        this.numero = numero;
        this.saldo = saldo;
    }

    public void sacar(double valor) {
        if (valor > saldo) {
            throw new IllegalArgumentException("Saldo insuficiente");
        }
        this.saldo -= valor;
    }
}

